    biography: "Tomas Kemtys is General Partner at Contrarian Ventures. His firm bio states he spent six years in investment banking at Centerview Partners, BNP Paribas and Societe Generale across London and New York, executing over $6 billion in transactions including in power and utilities. At Contrarian he covers LP fundraising, deal sourcing and execution, coaching colleagues and running founder events across Europe. He has led investments in Zoomo (UK), SunStore (Poland) and Beebop (Belgium), and holds positions in Decade, Vianova, Inbalance Grid, Bees&Bears and Cariqa. He is a long-standing board member of the Lithuanian Venture Capital Association and advises several family offices. He studied at ESADE Business School, UC San Diego and the University of Glasgow.",
