    biography: "Julian Counihan is General Partner of Schematic Ventures, the San Francisco early-stage fund he founded in 2017 around the thesis of 'technology that makes and moves the world'. His firm bio states he began his tech career as a software developer at Fortna building warehouse control and automation systems, then moved into technology investment banking before joining a New York-based fund investing in industrial hardware and supply chain. He holds a BS in systems engineering from the University of Virginia, earned magna cum laude, and an MBA from MIT. Schematic leads pre-seed and seed rounds with an average check of $1M-$2M into US and Canada based teams, and its published portfolio spans more than 30 companies including Flock Freight, Outrider, Platform Science, Plus One Robotics and Harbinger Motors. The New York fund is identified as Red Sea Ventures and the banking employer as Citi by NFX Signal rather than by Schematic's own site.",
