    biography: "Akio Tanaka is a Partner at Headline, based in Tokyo. He co-founded Infinity Ventures, the Asia firm that rebranded jointly with e.ventures to become Headline in May 2021, and he describes himself as an entrepreneur who unintentionally became a VC. He invests in consumer internet, fintech and SaaS. His portfolio includes Yeahka, freee, WealthNavi, OpenLogi, BuyandShip, PakPoBox and Zaiko. At the time of the rebrand he argued that every regional deal in future will have an international angle, and that VCs need international intelligence to find winners early.",
