    biography: "Christian Leybold is a Founding Partner of Headline, based in Berlin. He learned the American style of venture capital in Silicon Valley before launching the firm's European practice, a path he compares to a Catholic priest who spent time in the Vatican. His focus areas are consumer, marketplaces and healthcare. His portfolio includes Farfetch, Blinkist (acquired by Go1), CityDeal (acquired by Groupon), BrumBrum (acquired by Cazoo), Vicampo (acquired by VIVA Wine Group), Natural Cycles and Staffbase. He says investing is always about teams and that he enforces a no-asshole rule within the firm.",
