    biography: "Tal Abuloff is a Principal at Viola Ventures, where she focuses on early-stage fintech, SaaS and vertical AI investments. She spent four years as a Principal at Grove Ventures before joining Viola. Earlier in her career she clerked at the Supreme Court of Israel under Deputy Chief Justice Hanan Melcer, and she is an alumna of the IDF's Unit 8200. She holds an LL.M. from Harvard Law School, where she was a Fulbright Scholar and graduated with honors, and an LL.B. magna cum laude from Tel Aviv University. Her year of joining Viola Ventures is not disclosed on the fund's site.",
