    biography: "Jonathan Whittle is a co-founder and Managing Partner at Quona Capital, where he leads the firm's Latin America investment strategy from Washington, DC. Quona describes him as a seasoned investor and entrepreneur with over 25 years of experience in Latin America. He previously co-founded and served as CEO of Acesso, a Brazilian prepaid financial services company serving unbanked consumers. Before that he was a manager at Darby Technology Ventures, a technology venture fund for Latin America. Earlier in his career he was a founding team member at telecommunications and data services companies including Diveo, which was acquired by UOL, and Optiglobe, now Tivit. Quona's site does not publish his education or current board seats.",
