    biography: "Linda Yu is a Growth Partner at Quona Capital, which she joined in 2025. She previously spent five years as an Investment Partner at SoftBank Investment Advisers, where she helped establish the firm's Asia office and led investments across the US and Asia. From 2013 to 2018 she was a Private Equity Associate and then Vice President at Warburg Pincus, and she began her career as an analyst in the Technology Investment Banking Group at Bank of America Merrill Lynch. Quona says she has deployed and managed over $4 billion across technology-enabled businesses globally, with investments including KE Holdings (NYSE: BEKE), AInnovation (HKEX: 2121), Ziroom, Firework, Klook, Zuoyebang, M1 Finance and ARM. She holds dual bachelor's degrees from UC Berkeley and an MBA from Stanford, where she was an Arjay Miller Scholar.",
